python - <<'PY'
import json
from pathlib import Path

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

INPUTS = [
    ('source_a', '/data/source_a/users.json'),
    ('source_b', '/data/source_b/users.csv'),
    ('source_c', '/data/source_c/users.parquet'),
]
PRIORITY = [name for name, _ in INPUTS]
FIELDS = ['name', 'email', 'created_date', 'status']
ALIASES = {
    'user_id': ['user_id', 'id', 'userId'],
    'name': ['full_name', 'name', 'userName'],
    'email': ['email', 'email_address'],
    'created_date': ['registration_date', 'created_at', 'joined'],
    'status': ['status', 'is_active', 'active'],
}


def load_source(name, path):
    if path.endswith('.json'):
        with open(path, encoding='utf-8') as fh:
            data = json.load(fh)
        frame = pd.DataFrame(data)
    elif path.endswith('.csv'):
        frame = pd.read_csv(path)
    elif path.endswith('.parquet'):
        frame = pd.read_parquet(path)
    else:
        raise ValueError(f'Unsupported input: {path}')

    missing = [alias_group[0] for alias_group in [['user_id']] if not any(a in frame.columns for a in ALIASES[alias_group[0]])]
    if missing:
        raise ValueError(f'{name} is missing required user_id field')

    normalized = []
    for _, row in frame.iterrows():
        record = {}
        for field, aliases in ALIASES.items():
            value = None
            for alias in aliases:
                if alias in frame.columns and pd.notna(row[alias]):
                    value = row[alias]
                    break

            if field == 'user_id':
                if value is None or (isinstance(value, str) and not value.strip()):
                    raise ValueError(f'{name} contains a row without user_id')
                record[field] = int(value)
            elif field == 'created_date':
                if value is None or (isinstance(value, str) and not value.strip()):
                    record[field] = None
                else:
                    parsed = pd.to_datetime(value, errors='coerce')
                    if pd.isna(parsed):
                        raise ValueError(f'{name} has invalid date {value!r}')
                    record[field] = parsed.strftime('%Y-%m-%d')
            elif field == 'status':
                if value is None:
                    record[field] = None
                elif isinstance(value, bool):
                    record[field] = 'active' if value else 'inactive'
                elif isinstance(value, (int, float)) and value in (0, 1):
                    record[field] = 'active' if bool(value) else 'inactive'
                else:
                    text = str(value).strip()
                    lowered = text.lower()
                    if lowered in {'true', '1', 'yes', 'active'}:
                        record[field] = 'active'
                    elif lowered in {'false', '0', 'no', 'inactive'}:
                        record[field] = 'inactive'
                    else:
                        record[field] = text
            else:
                if value is None:
                    record[field] = None
                else:
                    text = str(value).strip()
                    record[field] = text if text else None
        normalized.append(record)

    return normalized


records_by_source = {
    source: load_source(source, path)
    for source, path in INPUTS
}

# Keep one normalized record per source/user. Inputs are expected to be unique by user_id.
source_users = {}
for source in PRIORITY:
    source_users[source] = {}
    for record in records_by_source[source]:
        user_id = record['user_id']
        if user_id in source_users[source]:
            raise ValueError(f'{source} contains duplicate user_id {user_id}')
        source_users[source][user_id] = record

all_user_ids = sorted({user_id for users in source_users.values() for user_id in users})
merged_rows = []
conflicts = []

for user_id in all_user_ids:
    available = {
        source: source_users[source][user_id]
        for source in PRIORITY
        if user_id in source_users[source]
    }
    merged = {'user_id': user_id}
    for field in FIELDS:
        selected = None
        for source in PRIORITY:
            if source in available and available[source][field] is not None:
                selected = available[source][field]
                break
        merged[field] = selected

        values = {
            source: available[source][field]
            for source in PRIORITY
            if source in available and available[source][field] is not None
        }
        if len(set(values.values())) > 1:
            conflicts.append({
                'user_id': user_id,
                'field': field,
                'values': values,
                'selected': selected,
            })
    merged_rows.append(merged)

# Explicit Arrow schema guarantees integer user_id and string output fields.
schema = pa.schema([
    ('user_id', pa.int64()),
    ('name', pa.string()),
    ('email', pa.string()),
    ('created_date', pa.string()),
    ('status', pa.string()),
])
columns = {
    field: [row[field] for row in merged_rows]
    for field in ['user_id', 'name', 'email', 'created_date', 'status']
}
table = pa.Table.from_pydict(columns, schema=schema)
pq.write_table(table, '/app/merged_users.parquet')

with open('/app/conflicts.json', 'w', encoding='utf-8') as fh:
    json.dump({'total_conflicts': len(conflicts), 'conflicts': conflicts}, fh, indent=2)
    fh.write('\n')

print(f'wrote {len(merged_rows)} merged users and {len(conflicts)} conflicts')
PY

